with with_dims as (select s.id, s.store_id, s.product_id, s.units, p2.opened_date from store_sales s left join stores p2 on s.store_id = p2.id) select date_trunc('week', opened_date) as week_start, product_id, round(avg(units), 2) as avg_units, count(distinct id) as distinct_ids, count(distinct id) as distinct_ids_2, percentile_approx(units, 0.95) as units_p95, grouping(date_trunc('week', opened_date)) as grouping_id from with_dims group by grouping sets ((date_trunc('week', opened_date), product_id), (date_trunc('week', opened_date))) having percentile_approx(units, 0.95) > 0 order by product_id desc;
